#!/usr/bin/env bash
# Makes the synthetic sources for the source check journeys into the folder
# given as $1. Every file is generated by ffmpeg from a test source: no real
# media is used. The files are not committed: scripts/e2e.sh makes them.
# Needs ffmpeg built with libx264, libvpx, libopus and libmp3lame.
# Last run with: ffmpeg version 6.1.1-3ubuntu5
set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "Usage: $0 <out-dir>" >&2
  exit 2
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
  echo "ffmpeg is missing: run scripts/setup.sh, or install ffmpeg." >&2
  exit 1
fi
out=$1
mkdir -p "$out"

# The tags test exactness: Vietnamese text, and an artist with a decomposed
# "Hà" (NFD), two spaces, then a precomposed "Nội" (NFC).
title='Mưa rơi nhẹ'
artist=$'Ha\xcc\x80  N\xe1\xbb\x99i'
composer='Lê Văn Thử'

# Each source lasts 2 s: a small test pattern at 15 frames per second, and a
# sine tone.
make() {
  ffmpeg -nostdin -hide_banner -loglevel error -y \
    -f lavfi -i 'testsrc2=size=64x36:rate=15:duration=2' \
    -f lavfi -i 'sine=frequency=440:sample_rate=48000:duration=2' \
    "$@"
}
vp9=(-c:v libvpx-vp9 -pix_fmt yuv420p -b:v 8k)
opus=(-c:a libopus -b:a 16k)

make -map 0:v -map 1:a -c:v libx264 -preset ultrafast -pix_fmt yuv420p -c:a aac \
  -metadata title="$title" -metadata artist="$artist" -metadata composer="$composer" "$out/song.mp4"
# The WebM has an artist only. ffmpeg writes a WebM title into the segment
# info, not as a tag, and Mediabunny reads only the tags.
make -map 0:v -map 1:a "${vp9[@]}" "${opus[@]}" -metadata artist="$artist" "$out/song.webm"
make -map 1:a -c:a libmp3lame -id3v2_version 4 \
  -metadata title="$title" -metadata artist="$artist" -metadata composer="$composer" "$out/song.mp3"
make -map 0:v "${vp9[@]}" -an "$out/video-only.webm"
# The timeline of this one starts at 1.5 s.
make -map 0:v -map 1:a "${vp9[@]}" "${opus[@]}" -output_ts_offset 1.5 "$out/late.webm"
# The stand-in karaoke track: audio only, 3 s, longer than the sources, so fitting cuts it.
ffmpeg -nostdin -hide_banner -loglevel error -y \
  -f lavfi -i 'sine=frequency=660:sample_rate=48000:duration=3' "${opus[@]}" "$out/karaoke.webm"
